/**
 * @fileoverview Defines the ProjectBoard component for managing project tasks with drag-and-drop functionality.
 * It supports light, dark, and sacred themes with comprehensive customization options.
 * Now with inline view transitions (Wolken-style) instead of dialog popups.
 */
'use client'

import React, { useMemo, useEffect, useState, useCallback, useRef } from 'react'
import {
  useProjectBoard,
  ProjectBoardProvider,
} from './context/ProjectBoardContext'

import Toolbar from '../Toolbar'
import { InlineShowTask } from './forms/ShowTask/inline'
import { InlineAddTask } from './forms/AddTask/inline'
import {
  ProjectBoardProps,
  ColumnData,
  Task,
  BoardType,
  AddTaskFormType,
  RawCompany,
  RawCustomer,
  RawProduct,
  ViewState,
} from './types'

import { useColumnDragAndDrop } from './utils/useDragandDrop/columns'
import { useTaskDragAndDrop } from './utils/useDragandDrop/tasks'
import Board from './board'
import { Breadcrumb } from './Breadcrumb'
import { AnimationWrapper } from './AnimationWrapper'
import cssStyles from './ProjectBoard.module.css'

// Stable empty reference lists for the variants that don't carry a given roster — module-level so
// the derived rawCompanies/rawCustomers/rawProducts keep a constant identity across renders (they
// feed useCallback/useMemo dependency arrays).
const EMPTY_COMPANIES: RawCompany[] = []
const EMPTY_CUSTOMERS: RawCustomer[] = []
const EMPTY_PRODUCTS: RawProduct[] = []

// --------------------------------------------------------------------------
// HELPER FUNCTIONS
// --------------------------------------------------------------------------

function mergeColumnsAndTasks(
  columns: Array<{ _id: string; title: string; description: string }>,
  tasks: Task[],
  boardType: BoardType
): ColumnData[] {
  return columns.map(col => {
    const colId = col._id
    const matchingTasks = tasks.filter(task => {
      switch (boardType) {
        case 'severityLevel':
          return task.severityId === colId
        case 'status':
          return task.statusId === colId
        case 'subStatus':
          return task.substatusId === colId
        case 'topic':
          return task.topicIds.includes(colId)
        default:
          return false
      }
    })
    return {
      _id: col._id,
      title: col.title,
      description: col.description,
      tasks: matchingTasks,
    }
  })
}

// --------------------------------------------------------------------------
// MAIN PROJECT BOARD CONTENT COMPONENT
// --------------------------------------------------------------------------

function ProjectBoardContent(props: ProjectBoardProps) {
  const {
    variant,
    boardType,
    columns,
    tasks,
    rawStatuses,
    rawSubStatuses,
    rawTopics,
    rawQueues,
    rawArticles,
    rawEmployees,
    rawServices,
    rawRegions,
    rawSeverityLevels,
    onEdit,
    onDelete,
    viewerRole = 'staff',
    onEditComment,
    onAdd,
    onComment,
    currentUser,
    customerId,
    companyId,
    preferDropdown,
    styles,
    permissions,
    meetings,
    onScheduleMeeting,
    onCancelMeeting,
    onConfirmMeeting,
    onRescheduleMeeting,
    meetingPermissions,
    currentDate,
    onUpdateCompanyNotes,
    onUpdateCustomerNotes,
    onCaseUpdate,
    employees,
    administrators,
    headingLevel = 2,
  } = props
  // rawCompanies exists ONLY on the administrator variant (narrowed off the `variant` discriminant);
  // company/customer boards default to the stable module empty. rawCustomers/rawProducts are
  // shared-optional base props.
  const rawCompanies =
    props.variant === 'administrator' ? props.rawCompanies : EMPTY_COMPANIES
  const rawCustomers = props.rawCustomers ?? EMPTY_CUSTOMERS
  const rawProducts = props.rawProducts ?? EMPTY_PRODUCTS
  const {
    columns: columnState,
    setColumns: setColumnState,
    viewState,
    setViewState,
    animationOrigin,
    setAnimationOrigin,
    activeAddTaskForm,
    setActiveAddTaskForm,
    activeTaskId,
    setActiveTaskId,
  } = useProjectBoard()

  const mergedColumns = useMemo<ColumnData[]>(
    () => mergeColumnsAndTasks(columns, tasks, boardType),
    [columns, tasks, boardType]
  )

  const isDisabled = styles?.disabled
  // The old getProjectBoardTheme defaulted to 'light' when no theme was given;
  // preserve that exact runtime default (the CSS base values are sacred, so a
  // light data-theme activates the light overrides — identical to before).
  const theme = styles?.theme ?? 'light'

  // Caller-supplied overrides (dimensions, spacing, custom colors, animation)
  // are mapped to the CSS custom properties the .container class consumes.
  // Only set a var when the caller actually provided a value so the CSS
  // theme defaults remain in effect otherwise.
  const containerStyle = useMemo<React.CSSProperties>(() => {
    const vars: Record<string, string> = {}
    const set = (name: string, value: string | undefined) => {
      if (value !== undefined) vars[name] = value
    }
    set('--pb-width', styles?.width)
    set('--pb-height', styles?.height)
    set('--pb-max-width', styles?.maxWidth)
    set('--pb-min-width', styles?.minWidth)
    set('--pb-max-height', styles?.maxHeight)
    set('--pb-min-height', styles?.minHeight)
    set('--pb-padding', styles?.padding)
    set('--pb-margin', styles?.margin)
    set('--pb-margin-top', styles?.marginTop)
    set('--pb-margin-bottom', styles?.marginBottom)
    set('--pb-margin-left', styles?.marginLeft)
    set('--pb-margin-right', styles?.marginRight)
    set('--pb-bg', styles?.backgroundColor)
    set('--pb-radius', styles?.borderRadius)
    set('--pb-shadow', styles?.boxShadow)
    set('--pb-backdrop', styles?.backdropFilter)
    set('--pb-bg-image', styles?.backgroundImage)
    set('--pb-container-animation', styles?.containerAnimation)
    set('--pb-glyph-color', styles?.glyphColor)
    set('--pb-glyph-font-size', styles?.glyphFontSize)
    set(
      '--pb-glyph-z',
      styles?.glyphZIndex !== undefined ? String(styles.glyphZIndex) : undefined
    )
    set('--pb-glyph-animation', styles?.glyphAnimation)
    set('--pb-toolbar-bg', styles?.toolbarBackground)
    set('--pb-toolbar-padding', styles?.toolbarPadding)
    set('--pb-toolbar-margin', styles?.toolbarMargin)
    set('--pb-toolbar-radius', styles?.toolbarBorderRadius)
    // Caller border override (borderColor + optional borderWidth).
    if (styles?.borderColor) {
      set(
        '--pb-border',
        `${styles.borderWidth || '1px'} solid ${styles.borderColor}`
      )
    }
    // Caller transition override.
    if (styles?.transitionDuration) {
      set(
        '--pb-transition',
        `all ${styles.transitionDuration} ${styles.transitionEasing || 'cubic-bezier(0.4, 0, 0.2, 1)'}`
      )
    }
    return vars as React.CSSProperties
  }, [styles])

  useEffect(() => {
    setColumnState(mergedColumns)
  }, [mergedColumns, setColumnState])

  // View-transition focus management (WCAG 2.4.3 Focus Order). Opening an inline
  // form is handled inside AnimationWrapper (focus moves into the revealed view);
  // here we handle the RETURN to the board: the "Back to Board" / "Cancel"
  // button that triggered the return has unmounted, so focus would be stranded
  // on <body>. Move it to the board region so keyboard / AT users resume there.
  const boardRegionRef = useRef<HTMLDivElement>(null)
  const previousViewStateRef = useRef<ViewState>(viewState)
  useEffect(() => {
    const previous = previousViewStateRef.current
    if (previous !== 'board' && viewState === 'board') {
      boardRegionRef.current?.focus({ preventScroll: true })
    }
    previousViewStateRef.current = viewState
  }, [viewState])

  // Local state
  const [selectedTaskId, setSelectedTaskId] = useState<string | null>(null)
  const [searchTerm, setSearchTerm] = useState('')
  const [productServiceFilter, setProductServiceFilter] =
    useState<string>('all')

  // Drag and drop hooks
  const columnDragAndDrop = useColumnDragAndDrop(columnState, setColumnState)
  const taskDragAndDrop = useTaskDragAndDrop()

  // Task selection handler - only toggles selection, doesn't open the task
  const handleTaskSelect = useCallback((taskId: string) => {
    setSelectedTaskId(prev => (prev === taskId ? null : taskId))
  }, [])

  // Search handler
  const handleSearchChange = useCallback((value: string) => {
    setSearchTerm(value)
  }, [])

  // Product/Service filter handler
  const handleProductServiceFilterChange = useCallback((value: string) => {
    setProductServiceFilter(value)
  }, [])

  // Filter columns based on search and product/service filter
  const filteredColumnState = useMemo(() => {
    let filtered = columnState

    // Apply product/service filter
    if (productServiceFilter !== 'all') {
      filtered = filtered.map(col => {
        const filteredTasks = col.tasks.filter(task => {
          // Check if task has productId or serviceId
          if (productServiceFilter === 'product') {
            return task.productId || task.productOrService === 'product'
          } else if (productServiceFilter === 'service') {
            return task.serviceId || task.productOrService === 'service'
          }
          return true
        })
        return { ...col, tasks: filteredTasks }
      })
    }

    // Apply search filter
    if (searchTerm) {
      const lowerTerm = searchTerm.toLowerCase()
      filtered = filtered.map(col => {
        const filteredTasks = col.tasks.filter(
          t =>
            t.title.toLowerCase().includes(lowerTerm) ||
            t.description.toLowerCase().includes(lowerTerm)
        )
        return { ...col, tasks: filteredTasks }
      })
    }

    return filtered
  }, [columnState, searchTerm, productServiceFilter])

  // Handle back to board navigation (defined early so other callbacks can use it)
  const handleBackToBoard = useCallback(() => {
    setViewState('board')
    setAnimationOrigin(null)
    setActiveAddTaskForm(null)
    setActiveTaskId(null)
  }, [setViewState, setAnimationOrigin, setActiveAddTaskForm, setActiveTaskId])

  // Task operations
  const handleAddTask = useCallback(
    (newTask: Omit<Task, '_id'>) => {
      const taskWithId = {
        ...newTask,
        _id: `task_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      }

      // Update local state
      setColumnState(prevColumns => {
        const newColumns = [...prevColumns]
        const targetColumnIndex = newColumns.findIndex(col => {
          switch (boardType) {
            case 'severityLevel':
              return col._id === newTask.severityId
            case 'status':
              return col._id === newTask.statusId
            case 'subStatus':
              return col._id === newTask.substatusId
            case 'topic':
              return newTask.topicIds.includes(col._id)
            default:
              return false
          }
        })

        if (targetColumnIndex !== -1) {
          const currentColumn = newColumns[targetColumnIndex]!
          newColumns[targetColumnIndex] = {
            _id: currentColumn._id,
            title: currentColumn.title,
            description: currentColumn.description,
            tasks: [...currentColumn.tasks, taskWithId],
          }
        }

        return newColumns
      })

      // Return to board view
      handleBackToBoard()
      onAdd(newTask)
    },
    [boardType, onAdd, setColumnState, handleBackToBoard]
  )

  const handleEditComment = useCallback(
    (commentId: string, newText: string, taskId: string) => {
      setColumnState(oldCols =>
        oldCols.map(col => {
          const updatedTasks = col.tasks.map(task => {
            if (task._id !== taskId) return task
            const updatedComments = task.comments.map(c => {
              if (c._id === commentId) {
                return { ...c, text: newText }
              }
              return c
            })
            return { ...task, comments: updatedComments }
          })
          return { ...col, tasks: updatedTasks }
        })
      )
      onEditComment(commentId, newText, taskId)
    },
    [onEditComment, setColumnState]
  )

  // Find current task for show view
  const currentShowTask = useMemo(() => {
    if (!activeTaskId) return null
    return columnState
      .flatMap(col => col.tasks)
      .find(task => task._id === activeTaskId)
  }, [columnState, activeTaskId])

  // Handle Create Task button click
  // Note: Animation origin is set to null for simplicity - the animation
  // will expand from center of viewport
  const handleCreateTaskClick = useCallback(() => {
    setAnimationOrigin(null)

    // Determine which form to show based on variant and preferDropdown
    let formType: AddTaskFormType = 'customer'
    if (variant === 'administrator') {
      formType =
        preferDropdown === true ||
        (preferDropdown !== false && rawCompanies && rawCompanies.length > 0)
          ? 'administratorCompanyDropdown'
          : 'administratorCompanyProvided'
    } else if (variant === 'company') {
      formType =
        preferDropdown === true ||
        (preferDropdown !== false && rawCustomers && rawCustomers.length > 0)
          ? 'companyCustomerDropdown'
          : 'companyCustomerProvided'
    }

    setActiveAddTaskForm(formType)
    setViewState('addTask')
  }, [
    setAnimationOrigin,
    variant,
    preferDropdown,
    rawCompanies,
    rawCustomers,
    setActiveAddTaskForm,
    setViewState,
  ])

  // Handle Show Task button click
  const handleShowTaskClick = useCallback(() => {
    if (!selectedTaskId) return

    // Verify the task exists before transitioning
    const taskExists = columnState
      .flatMap(col => col.tasks)
      .some(task => task._id === selectedTaskId)

    if (!taskExists) {
      console.warn(`Task with ID ${selectedTaskId} not found in columnState`)
      return
    }

    // Animation origin is set to null for simplicity
    setAnimationOrigin(null)
    setActiveTaskId(selectedTaskId)
    setViewState('showTask')
  }, [
    selectedTaskId,
    columnState,
    setAnimationOrigin,
    setActiveTaskId,
    setViewState,
  ])

  // Toolbar buttons - respect permissions
  const buttons = useMemo(() => {
    const btns = []
    // Only show Create Task button if user has write permissions
    if (!permissions || permissions.access === 'write') {
      btns.push({
        text: 'Create Task',
        onClick: handleCreateTaskClick,
      })
    }
    btns.push({
      text: 'Manage',
      onClick: handleShowTaskClick,
      disabled: !selectedTaskId,
    })
    return btns
  }, [selectedTaskId, permissions, handleCreateTaskClick, handleShowTaskClick])

  // Render add task form based on active form type
  const renderAddTaskForm = () => {
    if (viewState !== 'addTask' || !activeAddTaskForm) return null

    // Unified inline form for all variants
    return (
      <InlineAddTask
        headingLevel={headingLevel}
        onAdd={handleAddTask}
        onCancel={handleBackToBoard}
        topics={rawTopics}
        severityLevels={rawSeverityLevels}
        statuses={rawStatuses}
        subStatuses={rawSubStatuses}
        createdUserId={currentUser._id}
        companyId={companyId}
        customerId={customerId}
        {...(activeAddTaskForm === 'administratorCompanyDropdown'
          ? { rawCompanies }
          : {})}
        {...(activeAddTaskForm === 'companyCustomerDropdown'
          ? { rawCustomers }
          : {})}
        {...(variant === 'company' || variant === 'customer'
          ? { rawProducts }
          : {})}
        rawServices={rawServices}
        rawRegions={rawRegions}
        knowledgebaseArticles={rawArticles}
        // The customer board's create panel is the customer's REQUEST form: subject, description,
        // severity and the product/service the company requires — never the staff triage fields.
        viewerRole={variant === 'customer' ? 'customer' : 'staff'}
        {...(props.variant === 'customer'
          ? {
              requireProduct: props.requireProduct === true,
              requireService: props.requireService === true,
            }
          : {})}
        styles={styles}
      />
    )
  }

  // Render show task form
  const renderShowTaskForm = () => {
    if (viewState !== 'showTask' || !currentShowTask || !activeTaskId)
      return null

    const setSeverity =
      !permissions || permissions.access === 'write'
        ? (props.onSetSeverity ??
          (props.variant === 'customer' ? props.onRaiseSeverity : undefined))
        : undefined

    const editCallback = (updatedData: any) => {
      if (!permissions || permissions.access === 'write') {
        onEdit({ _id: activeTaskId, ...updatedData })
      }
    }

    // Undefined when the caller withheld onDelete, which is what removes the
    // control rather than disabling it (the onUpdateCustomerNotes contract).
    const deleteCallback = onDelete
      ? () => {
          if (!permissions || permissions.access === 'write') {
            onDelete({ _id: activeTaskId })
            handleBackToBoard()
          }
        }
      : undefined

    const commentCallback = (text: string, _id: string) => {
      if (!permissions || permissions.access === 'write') {
        onComment(text, _id)
      }
    }

    const editCommentCallback = (commentId: string, newText: string) => {
      if (!permissions || permissions.access === 'write') {
        handleEditComment(commentId, newText, activeTaskId)
      }
    }

    // The meeting props below are forwarded by CONDITIONAL SPREAD rather than
    // passed directly: under `exactOptionalPropertyTypes` an explicit
    // `undefined` is not assignable to an optional prop, and a WITHHELD meeting
    // handler is the entire point — its absence is what hides the control. Same
    // shape the file already uses for onCaseUpdate / employees / administrators.
    return (
      <InlineShowTask
        headingLevel={headingLevel}
        taskId={activeTaskId}
        taskTitle={currentShowTask.title}
        createdBy={currentShowTask.createdBy}
        description={currentShowTask.description}
        comments={currentShowTask.comments}
        caseUpdates={currentShowTask.caseUpdates}
        customerAssigned={currentShowTask.customerAssigned}
        associatedCompanyId={currentShowTask.companyId}
        {...(currentShowTask.companyInternalNotes !== undefined && {
          companyInternalNotes: currentShowTask.companyInternalNotes,
        })}
        {...(onUpdateCompanyNotes && { onUpdateCompanyNotes })}
        associatedCustomerId={currentShowTask.customerId}
        {...(currentShowTask.customerInternalNotes !== undefined && {
          customerInternalNotes: currentShowTask.customerInternalNotes,
        })}
        severity={currentShowTask.severity}
        schedulingQueue={currentShowTask.schedulingQueue}
        status={currentShowTask.status}
        subStatus={currentShowTask.subStatus}
        topics={currentShowTask.topicLabels}
        knowledgebaseArticles={currentShowTask.kbArticles}
        teamMemberAssigned={currentShowTask.teamMember}
        nextActionDate={currentShowTask.nextActionDate}
        currentUserName={`${currentUser.firstName} ${currentUser.lastName}`}
        productOrService={currentShowTask.productOrService}
        productServiceName={currentShowTask.productServiceName}
        productId={currentShowTask.productId}
        serviceId={currentShowTask.serviceId}
        region={currentShowTask.region}
        onEdit={editCallback}
        {...(deleteCallback && { onDelete: deleteCallback })}
        viewerRole={viewerRole}
        onComment={commentCallback}
        onEditComment={editCommentCallback}
        {...(onUpdateCustomerNotes && { onUpdateCustomerNotes })}
        onBack={handleBackToBoard}
        severityOptions={rawSeverityLevels}
        schedulingQueueOptions={rawQueues}
        statusOptions={rawStatuses}
        subStatusOptions={rawSubStatuses}
        topicOptions={rawTopics}
        knowledgebaseArticleOptions={rawArticles}
        teamMemberOptions={rawEmployees}
        rawProducts={rawProducts ?? []}
        rawServices={rawServices}
        regionOptions={rawRegions}
        styles={styles}
        meetings={meetings.filter(m => m.taskId === activeTaskId)}
        {...(setSeverity && { onSetSeverity: setSeverity })}
        {...(props.variant === 'customer' && props.onCustomerSetStatus
          ? {
              onCustomerSetStatus: props.onCustomerSetStatus,
              customerAllowedStatuses: props.customerAllowedStatuses ?? [],
              customerAllowedSubStatuses:
                props.customerAllowedSubStatuses ?? [],
            }
          : {})}
        {...(onScheduleMeeting && { onScheduleMeeting })}
        {...(onCancelMeeting && { onCancelMeeting })}
        {...(onConfirmMeeting && { onConfirmMeeting })}
        {...(onRescheduleMeeting && { onRescheduleMeeting })}
        {...(meetingPermissions && { meetingPermissions })}
        currentDate={currentDate}
        variant={variant === 'customer' ? 'customer' : 'employee'}
        {...(onCaseUpdate && { onCaseUpdate })}
        {...(employees && { employees })}
        {...(administrators && { administrators })}
      />
    )
  }

  return (
    <div
      className={cssStyles.container}
      data-component="ProjectBoard"
      data-theme={theme}
      {...(isDisabled && { 'data-disabled': 'true' })}
      style={containerStyle}
    >
      {/* Show breadcrumb when not on board view */}
      {viewState !== 'board' && (
        <Breadcrumb
          viewState={viewState}
          onBack={handleBackToBoard}
          {...(styles && { styles })}
        />
      )}

      {/* Board View */}
      {viewState === 'board' && (
        <>
          <Toolbar
            buttons={buttons}
            filterDropdown={{
              label: 'Type',
              options: [
                { value: 'all', _id: 'all' },
                { value: 'product', _id: 'product' },
                { value: 'service', _id: 'service' },
              ],
              value: productServiceFilter,
              onChange: handleProductServiceFilterChange,
            }}
            searchbarProps={{
              label: 'Search...',
              value: searchTerm,
              onChange: handleSearchChange,
              styles: { theme: styles?.theme || 'light' },
            }}
            styles={{ theme: styles?.theme || 'light' }}
          />

          <div
            className={cssStyles.toolbarContainer}
            ref={boardRegionRef}
            tabIndex={-1}
          >
            <Board
              headingLevel={headingLevel}
              columns={filteredColumnState}
              selectedTaskId={selectedTaskId}
              onTaskSelect={handleTaskSelect}
              columnDragAndDrop={columnDragAndDrop}
              taskDragAndDrop={taskDragAndDrop}
              styles={{ theme: styles?.theme || 'light' }}
            />
          </div>
        </>
      )}

      {/* Add Task Form View - Inline with Animation */}
      <AnimationWrapper
        origin={animationOrigin}
        isVisible={viewState === 'addTask'}
        {...(styles && { styles })}
      >
        {renderAddTaskForm()}
      </AnimationWrapper>

      {/* Show Task Form View - Inline with Animation */}
      <AnimationWrapper
        origin={animationOrigin}
        isVisible={viewState === 'showTask'}
        {...(styles && { styles })}
      >
        {renderShowTaskForm()}
      </AnimationWrapper>
    </div>
  )
}

// --------------------------------------------------------------------------
// MAIN PROJECT BOARD WRAPPER COMPONENT
// --------------------------------------------------------------------------

function ProjectBoard(props: ProjectBoardProps) {
  return (
    <ProjectBoardProvider>
      <ProjectBoardContent {...props} />
    </ProjectBoardProvider>
  )
}

export default ProjectBoard
